// FUNCTION: BFME2 0x00483B10 size=45 name=?rva00483B10@Rva00483B10@@UAEXH@Z evidence=?:placeholder
void SupplyWarehouseCripplingBehavior::onDamage(DamageInfo *damageInfo)
{
	UnsignedInt now = TheGameLogic->getFrame();
	resetSelfHealSupression();
	// hit: sleep until the healing is allowed again
	setWakeFrame(getObject(), UPDATE_SLEEP(m_healingSupressedUntilFrame - now));
}

// FUNCTION: BFME2 0x00483B3D size=102 name=?update@Rva00483B3D@@QAEHXZ evidence=?:placeholder
UpdateSleepTime SupplyWarehouseCripplingBehavior::update()
{
	// suppression is handled by sleeping the module, so being here means it is time to heal
	const SupplyWarehouseCripplingBehaviorModuleData *data = (const SupplyWarehouseCripplingBehaviorModuleData *)m_moduleData;
	UnsignedInt now = TheGameLogic->getFrame();
	m_nextHealingFrame = now + data->m_selfHealDelay;

	getObject()->attemptHealing(data->m_selfHealAmount, NULL);

	if (getObject()->getBodyModule()->getHealth() == getObject()->getBodyModule()->getMaxHealth())
		return UPDATE_SLEEP_FOREVER;

	// the delay between heals is handled by sleeping too
	return UPDATE_SLEEP(m_nextHealingFrame - now);
}

// FUNCTION: BFME2 0x00483BA3 size=24 name=?rva00483BA3@Rva00483BA3@@QAEXXZ evidence=?:placeholder
void SupplyWarehouseCripplingBehavior::resetSelfHealSupression()
{
	const SupplyWarehouseCripplingBehaviorModuleData *data = (const SupplyWarehouseCripplingBehaviorModuleData *)m_moduleData;
	UnsignedInt now = TheGameLogic->getFrame();

	m_healingSupressedUntilFrame = now + data->m_selfHealSupression;
	m_nextHealingFrame = m_healingSupressedUntilFrame;
}

// FUNCTION: BFME2 0x00483BBB size=18 name=?bfmeGoBEC@BfmeThingBEC@@QAEXXZ evidence=N:ledger
void SupplyWarehouseCripplingBehavior::startCrippledEffects()
{
	DockUpdateInterface *dock = getObject()->getDockUpdateInterface();
	dock->setDockCrippled(true);
}

// FUNCTION: BFME2 0x00483BCD size=18 name=?bfmeGo940D@BfmeThing940D@@QAEXXZ evidence=N:ledger
void SupplyWarehouseCripplingBehavior::stopCrippledEffects()
{
	DockUpdateInterface *dock = getObject()->getDockUpdateInterface();
	dock->setDockCrippled(false);
}

// FUNCTION: BFME2 0x00483BDF size=59 name=?xfer@Rva004839D3@@MAEXPAVXfer@@@Z evidence=?:placeholder
void SupplyWarehouseCripplingBehavior::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);
	if (!xfer->IsLightCRC())
	{
		xfer->Version1();
		*xfer == m_healingSupressedUntilFrame;
		*xfer == m_nextHealingFrame;
	}
}

